def carry_over_pending_tokens(apps, schema_editor):
    """Keep tokens working for videos still waiting for their original, so
    an edit page open across the deploy can still upload. Everything else
    gets a fresh token when it next asks."""
    Video = apps.get_model("fk", "Video")
    UploadToken = apps.get_model("fk", "UploadToken")
    expires = timezone.now() + timedelta(hours=24)
    UploadToken.objects.bulk_create(
        UploadToken(video_id=video_id, token=token, expires=expires)
        for video_id, token in Video.objects.filter(proper_import=False)
        .exclude(upload_token="")
        .values_list("id", "upload_token")
    )


